def attrs = ctx.containsKey('Attributes') ? ctx.Attributes : (ctx.containsKey('attributes') ? ctx.attributes : [:]);
for (def key : ['requestId','correlationId','transactionId','traceId','workflowId','workflow','operation','workflowStep','eventType','outcome','durationMs']) {
  if (attrs.containsKey(key)) ctx[key] = attrs[key];
}
for (def entry : attrs.entrySet()) { if (entry.getKey().endsWith('Id')) ctx[entry.getKey()] = entry.getValue(); }
def identifierKeys = attrs.containsKey('identifierKeys') ? attrs.identifierKeys : (ctx.containsKey('identifierKeys') ? ctx.identifierKeys : []);
if (identifierKeys instanceof String) identifierKeys = identifierKeys.splitOnToken(',');
for (def key : identifierKeys) { if (attrs.containsKey(key)) ctx[key] = attrs[key]; }
if ((!ctx.containsKey('operation') || ctx.operation == '<unspecified span name>') && ctx.containsKey('Name')) ctx.operation = ctx.Name;
if (ctx.containsKey('TraceId')) ctx.traceId = ctx.TraceId;
if (ctx.containsKey('trace') && ctx.trace instanceof Map && ctx.trace.containsKey('id')) ctx.traceId = ctx.trace.id;
if (ctx.containsKey('Resource')) {
  def r = ctx.Resource;
  if (r.containsKey('service.name')) ctx.serviceName = r['service.name'];
  else if (r.containsKey('service') && r.service instanceof Map) ctx.serviceName = r.service.name;
}
if (ctx.containsKey('service.name')) ctx.serviceName = ctx['service.name'];
if (ctx.containsKey('service') && ctx.service instanceof Map && ctx.service.containsKey('name')) ctx.serviceName = ctx.service.name;
if (!ctx.containsKey('serviceName')) ctx.serviceName = 'unknown';
if (ctx.containsKey('Duration') && !ctx.containsKey('durationMs')) ctx.durationMs = ctx.Duration / 1000.0;
if (!ctx.containsKey('outcome') && ctx.containsKey('TraceStatus')) ctx.outcome = ctx.TraceStatus == 2 ? 'failure' : 'success';
if (ctx['_index'].startsWith('logs-')) {
  if (ctx.containsKey('eventType')) ctx.relatedEventType = ctx.eventType;
  ctx.eventType = 'Log';
} else if (!ctx.containsKey('eventType')) ctx.eventType = ctx['_index'].startsWith('metrics-') ? 'Metric' : 'Workflow';

if (attrs.containsKey('status')) ctx.status = attrs.status;
if (attrs.containsKey('http.response.status_code')) ctx.httpStatusCode = attrs['http.response.status_code'];
else if (attrs.http instanceof Map && attrs.http.response instanceof Map && attrs.http.response.containsKey('status_code')) ctx.httpStatusCode = attrs.http.response.status_code;
if (attrs.containsKey('db.operation.name')) ctx.dbOperation = attrs['db.operation.name'];
else if (attrs.db instanceof Map && attrs.db.operation instanceof Map && attrs.db.operation.containsKey('name')) ctx.dbOperation = attrs.db.operation.name;
if (attrs.containsKey('exception.type')) ctx.exceptionType = attrs['exception.type'];
else if (attrs.exception instanceof Map && attrs.exception.containsKey('type')) ctx.exceptionType = attrs.exception.type;
if (attrs.containsKey('exception.message')) ctx.exceptionMessage = attrs['exception.message'];
else if (attrs.exception instanceof Map && attrs.exception.containsKey('message')) ctx.exceptionMessage = attrs.exception.message;
